const ENV_KEY_REGEX = /^[A-Za-z_][A-Za-z0-9_]*$/;

const ENV_TEMPLATE_BASENAME_REGEX = /^(\.env(\.[A-Za-z0-9_-]+)?\.example|\.dev\.vars\.example)$/;
const LOCAL_ENV_BASENAME_REGEX = /^(\.env(\.[A-Za-z0-9_-]+)?|\.dev\.vars(\.[A-Za-z0-9_-]+)?)$/;

function getBaseName(path: string): string {
  const normalized = path.replace(/\\/g, '/');
  const parts = normalized.split('/');
  return parts[parts.length - 1];
}

function uniqueSorted(values: Iterable<string>): string[] {
  return Array.from(new Set(values)).sort((a, b) => a.localeCompare(b));
}

function parseKeyValueLine(line: string): { key: string; value: string; comment: string } | null {
  const trimmed = line.trim();
  if (!trimmed || trimmed.startsWith('#')) {
    return null;
  }

  const withoutExport = trimmed.startsWith('export ') ? trimmed.slice('export '.length).trim() : trimmed;
  const equalIndex = withoutExport.indexOf('=');
  if (equalIndex < 0) {
    return null;
  }

  const key = withoutExport.slice(0, equalIndex).trim();
  if (!ENV_KEY_REGEX.test(key)) {
    return null;
  }

  const rest = withoutExport.slice(equalIndex + 1);
  const commentIndex = rest.indexOf('#');

  if (commentIndex === -1) {
    return { key, value: rest.trim(), comment: '' };
  }

  return {
    key,
    value: rest.slice(0, commentIndex).trim(),
    comment: rest.slice(commentIndex + 1).trim(),
  };
}

function parseValue(value: string): string {
  const trimmed = value.trim();
  if (
    (trimmed.startsWith('"') && trimmed.endsWith('"')) ||
    (trimmed.startsWith("'") && trimmed.endsWith("'"))
  ) {
    return trimmed.slice(1, -1);
  }

  return trimmed;
}

export function parseEnvTemplateContent(content: string): ParsedEnvTemplate {
  const required = new Set<string>();
  const optional = new Set<string>();

  for (const line of content.split(/\r?\n/)) {
    const parsed = parseKeyValueLine(line);
    if (!parsed) {
      continue;
    }

    if (parsed.comment.toLowerCase().includes('optional')) {
      optional.add(parsed.key);
      required.delete(parsed.key);
    } else {
      required.add(parsed.key);
      optional.delete(parsed.key);
    }
  }

  return {
    requiredKeys: uniqueSorted(required),
    optionalKeys: uniqueSorted(optional),
  };
}

export function isEnvTemplatePath(path: string): boolean {
  return ENV_TEMPLATE_BASENAME_REGEX.test(getBaseName(path));
}

export function isLocalEnvPath(path: string): boolean {
  const baseName = getBaseName(path);
  if (!LOCAL_ENV_BASENAME_REGEX.test(baseName)) {
    return false;
  }

  return !baseName.endsWith('.example');
}

export function parseEnvFileContent(content: string): Map<string, string> {
  const values = new Map<string, string>();

  for (const line of content.split(/\r?\n/)) {
    const parsed = parseKeyValueLine(line);
    if (!parsed) {
      continue;
    }

    values.set(parsed.key, parseValue(parsed.value));
  }

  return values;
}

export function collectEnvTemplates(templateFiles: EnvTemplateFile[]): ParsedEnvTemplate {
  const required = new Set<string>();
  const optional = new Set<string>();

  for (const templateFile of templateFiles) {
    const parsed = parseEnvTemplateContent(templateFile.content);

    for (const key of parsed.requiredKeys) {
      required.add(key);
      optional.delete(key);
    }

    for (const key of parsed.optionalKeys) {
      if (!required.has(key)) {
        optional.add(key);
      }
    }
  }

  return {
    requiredKeys: uniqueSorted(required),
    optionalKeys: uniqueSorted(optional),
  };
}

export function resolveEnvPreflight(input: ResolveEnvPreflightInput): EnvPreflightResult {
  const values = new Map<string, ResolvedEnvValue>();
  const allKeys = uniqueSorted([...input.requiredKeys, ...input.optionalKeys]);

  for (const key of allKeys) {
    if (input.explicitEnv.has(key)) {
      values.set(key, {
        value: input.explicitEnv.get(key) ?? '',
        source: 'explicit',
      });
      continue;
    }

    if (input.localEnv.has(key)) {
      values.set(key, {
        value: input.localEnv.get(key) ?? '',
        source: 'local',
      });
      continue;
    }

    if (input.processEnv.has(key)) {
      values.set(key, {
        value: input.processEnv.get(key) ?? '',
        source: 'process',
      });
    }
  }

  const missingRequiredKeys = input.requiredKeys.filter((key) => !values.has(key)).sort((a, b) => a.localeCompare(b));

  return {
    values,
    missingRequiredKeys,
  };
}

export function computeEnvFingerprint(values: ReadonlyMap<string, string>): string {
  const normalized = Array.from(values.entries())
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([key, value]) => `${key}\u0000${value}`)
    .join('\u0001');

  return createHash('sha256').update(normalized).digest('hex');
}

import { strict as assert } from 'assert';
import {
  parseGitLogOutput,
  parseGitLsTreeNameOnlyOutput,
  treeOutputHasSubmodule,
} from './git.js';

export function runCheckpointGitTests(): void {
  {
    const parsed = parseGitLogOutput(
      'sha_one\u001ffeat: one\\n\\nBody\u001esha_two\u001ffix: two\u001e'
    );

    assert.deepEqual(parsed, [
      { sha: 'sha_one', message: 'feat: one\\n\\nBody' },
      { sha: 'sha_two', message: 'fix: two' },
    ]);
  }

  {
    const parsed = parseGitLsTreeNameOnlyOutput('package.json\napps/web/package.json\n\n');
    assert.deepEqual(parsed, ['package.json', 'apps/web/package.json']);
  }

  {
    const hasSubmodule = treeOutputHasSubmodule(
      '100644 blob abc123\tREADME.md\n160000 commit deadbeef\tvendor/lib\n'
    );
    assert.equal(hasSubmodule, true);
  }

  {
    const hasSubmodule = treeOutputHasSubmodule('100644 blob abc123\tREADME.md\n');
    assert.equal(hasSubmodule, false);
  }
}

import { execFileSync } from 'child_process';
import type { CommitHistoryEntry, TreeFileEntry } from './resolver.js';

export function parseGitLogOutput(output: string): CommitHistoryEntry[] {
  const records = output.split('\u001e').map((record) => record.trim()).filter(Boolean);
  const commits: CommitHistoryEntry[] = [];

  for (const record of records) {
    const separatorIndex = record.indexOf('\u001f');
    if (separatorIndex < 0) {
      continue;
    }

    const sha = record.slice(0, separatorIndex).trim();
    const message = record.slice(separatorIndex + 1);
    if (!sha) {
      continue;
    }

    commits.push({ sha, message });
  }

  return commits;
}

export function parseGitLsTreeNameOnlyOutput(output: string): string[] {
  return output
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);
}

export function treeOutputHasSubmodule(output: string): boolean {
  return output
    .split(/\r?\n/)
    .some((line) => line.trim().startsWith('160000 '));
}

function normalizeGitError(error: unknown): string {
  if (error && typeof error === 'object' && 'stderr' in error) {
    const stderr = (error as { stderr?: string | Buffer }).stderr;
    if (typeof stderr === 'string' && stderr.trim()) {
      return stderr.trim();
    }

    if (stderr && Buffer.isBuffer(stderr) && stderr.toString('utf8').trim()) {
      return stderr.toString('utf8').trim();
    }
  }

  if (error instanceof Error && error.message) {
    return error.message;
  }

  return String(error);
}

export class GitRepo {
  constructor(private readonly cwd: string = process.cwd()) {}

  run(args: string[]): string {
    try {
      return execFileSync('git', args, {
        cwd: this.cwd,
        encoding: 'utf8',
        stdio: ['ignore', 'pipe', 'pipe'],
      }).toString();
    } catch (error) {
      throw new Error(`git ${args.join(' ')} failed: ${normalizeGitError(error)}`);
    }
  }

  resolveCommitSha(commitish: string): string {
    const resolved = this.run(['rev-parse', '--verify', `${commitish}^{commit}`]).trim();
    if (!resolved) {
      throw new Error(`Unable to resolve commit-ish: ${commitish}`);
    }
    return resolved;
  }

  getCommitMessage(sha: string): string {
    return this.run(['show', '-s', '--format=%B', sha]);
  }

  listCommits(ref: string): CommitHistoryEntry[] {
    const output = this.run(['log', '--format=%H%x1f%B%x1e', ref]);
    return parseGitLogOutput(output);
  }

  getCurrentBranchRef(): string | null {
    try {
      const output = this.run(['symbolic-ref', '--quiet', '--short', 'HEAD']).trim();
      return output || null;
    } catch {
      return null;
    }
  }

  listTreePaths(sha: string): string[] {
    const output = this.run(['ls-tree', '-r', '--name-only', sha]);
    return parseGitLsTreeNameOnlyOutput(output);
  }

  readFileAtCommit(sha: string, path: string): string {
    return this.run(['show', `${sha}:${path}`]);
  }

  listTreeFileEntriesForProjectDetection(sha: string): TreeFileEntry[] {
    const paths = this.listTreePaths(sha);
    const entries: TreeFileEntry[] = [];

    for (const path of paths) {
      if (path.endsWith('/package.json') || path === 'package.json') {
        entries.push({
          path,
          content: this.readFileAtCommit(sha, path),
        });
      } else {
        entries.push({ path });
      }
    }

    return entries;
  }

  ensureNoSubmodules(sha: string): void {
    const output = this.run(['ls-tree', '-r', sha]);
    if (treeOutputHasSubmodule(output)) {
      throw new Error(
        'Checkpoint deploy does not support git submodules in MVP. Remove submodules or choose a different commit.'
      );
    }
  }

  ensureNoGitLfs(sha: string): void {
    const treePaths = this.listTreePaths(sha);
    const gitattributesPaths = treePaths.filter(
      (path) => path === '.gitattributes' || path.endsWith('/.gitattributes')
    );

    for (const path of gitattributesPaths) {
      const content = this.readFileAtCommit(sha, path);
      if (/\bfilter=lfs\b/.test(content)) {
        throw new Error(
          'Checkpoint deploy does not support Git LFS in MVP. Remove LFS tracking or choose a different commit.'
        );
      }
    }
  }
}

import { strict as assert } from 'assert';
import {
  detectProjectRootCandidates,
  extractEntireSessionId,
  parseCommitTrailers,
  parseDeployInput,
  resolveCheckpointFromHistory,
  selectProjectRoot,
} from './resolver.js';

export function runCheckpointResolverTests(): void {
  {
    const parsed = parseDeployInput('checkpoint:8a513f56ed70');
    assert.deepEqual(parsed, { kind: 'checkpoint', checkpointId: '8a513f56ed70' });
  }

  {
    const parsed = parseDeployInput('8a513f56ed70');
    assert.deepEqual(parsed, { kind: 'checkpoint', checkpointId: '8a513f56ed70' });
  }

  {
    const parsed = parseDeployInput('commit:main~1');
    assert.deepEqual(parsed, { kind: 'commit', commitish: 'main~1' });
  }

  {
    const parsed = parseDeployInput('v1.2.3');
    assert.deepEqual(parsed, { kind: 'commit', commitish: 'v1.2.3' });
  }

  assert.throws(
    () => parseDeployInput('checkpoint:not-a-hex'),
    /Checkpoint ID must be 12 hexadecimal characters/
  );

  {
    const trailers = parseCommitTrailers(`feat: add thing\n\nBody\n\nEntire-Checkpoint: 8a513f56ed70\nEntire-Attribution: {"sessionId":"sess_123"}`);
    assert.equal(trailers.checkpointId, '8a513f56ed70');
    assert.equal(trailers.entireAttribution, '{"sessionId":"sess_123"}');
    assert.equal(trailers.entireSessionId, 'sess_123');
  }

  {
    const trailers = parseCommitTrailers(
      `fix: adjust\n\nEntire-Attribution: source=entire session_id=sess_456 actor=ai`
    );
    assert.equal(trailers.entireSessionId, 'sess_456');
  }

  {
    const result = resolveCheckpointFromHistory('8a513f56ed70', [
      {
        sha: 'sha_newest',
        message: 'feat\n\nEntire-Checkpoint: 8a513f56ed70',
      },
      {
        sha: 'sha_older',
        message: 'feat\n\nEntire-Checkpoint: 8a513f56ed70',
      },
      {
        sha: 'sha_other',
        message: 'feat\n\nEntire-Checkpoint: ffffffffffff',
      },
    ]);

    assert.equal(result.selected.sha, 'sha_newest');
    assert.equal(result.matchCount, 2);
  }

  assert.throws(
    () =>
      resolveCheckpointFromHistory('8a513f56ed70', [
        {
          sha: 'sha_1',
          message: 'feat\n\nEntire-Checkpoint: ffffffffffff',
        },
      ]),
    /No commit found with trailer Entire-Checkpoint: 8a513f56ed70/
  );

  {
    const root = selectProjectRoot([
      {
        path: '.',
        signals: ['package_json', 'lockfile'],
      },
    ]);
    assert.equal(root.path, '.');
  }

  assert.throws(
    () =>
      selectProjectRoot([
        { path: 'apps/web', signals: ['package_json', 'lockfile'] },
        { path: 'apps/docs', signals: ['package_json', 'framework_config'] },
      ]),
    /Multiple deployable project roots detected/
  );

  {
    const candidates = detectProjectRootCandidates([
      { path: 'apps/web/package.json', content: '{"name":"web"}' },
      { path: 'apps/web/pnpm-lock.yaml' },
      { path: 'apps/docs/package.json', content: '{"name":"docs"}' },
      { path: 'apps/docs/README.md' },
    ]);

    assert.deepEqual(candidates, [
      {
        path: 'apps/web',
        signals: ['lockfile', 'package_json'],
      },
    ]);
  }

  {
    const candidates = detectProjectRootCandidates([
      {
        path: 'package.json',
        content: JSON.stringify({
          name: 'root-app',
          scripts: {
            build: 'vite build',
          },
        }),
      },
    ]);

    assert.deepEqual(candidates, [
      {
        path: '.',
        signals: ['build_script', 'package_json'],
      },
    ]);
  }

  assert.equal(extractEntireSessionId(null), null);
}

const CHECKPOINT_ID_REGEX = /^[a-f0-9]{12}$/i;

export type ParsedDeployInput =
  | { kind: 'checkpoint'; checkpointId: string }
  | { kind: 'commit'; commitish: string };

export interface ParsedTrailers {
  checkpointId: string | null;
  entireAttribution: string | null;
  entireSessionId: string | null;
}

export interface CommitHistoryEntry {
  sha: string;
  message: string;
}

export interface CheckpointResolutionFromHistory {
  selected: {
    sha: string;
    trailers: ParsedTrailers;
  };
  matchCount: number;
  matchedShas: string[];
}

export interface ProjectRootCandidate {
  path: string;
  signals: string[];
}

export interface TreeFileEntry {
  path: string;
  content?: string;
}

const LOCKFILE_NAMES = new Set([
  'pnpm-lock.yaml',
  'package-lock.json',
  'yarn.lock',
  'bun.lock',
  'bun.lockb',
]);

const FRAMEWORK_CONFIG_REGEXES = [
  /^(next|nuxt|astro|vite|svelte|remix)\.config(\.[a-z]+)?$/,
  /^angular\.json$/,
  /^gatsby-config\.[a-z]+$/,
];

export function isCheckpointId(value: string): boolean {
  return CHECKPOINT_ID_REGEX.test(value);
}

export function parseDeployInput(input: string): ParsedDeployInput {
  const raw = input.trim();
  if (!raw) {
    throw new Error('Missing checkpoint ID or commit-ish input');
  }

  if (raw.toLowerCase().startsWith('checkpoint:')) {
    const checkpointId = raw.slice('checkpoint:'.length).trim();
    if (!isCheckpointId(checkpointId)) {
      throw new Error('Checkpoint ID must be 12 hexadecimal characters');
    }
    return { kind: 'checkpoint', checkpointId: checkpointId.toLowerCase() };
  }

  if (isCheckpointId(raw)) {
    return { kind: 'checkpoint', checkpointId: raw.toLowerCase() };
  }

  if (raw.toLowerCase().startsWith('commit:')) {
    const commitish = raw.slice('commit:'.length).trim();
    if (!commitish) {
      throw new Error('Missing commit-ish after commit: prefix');
    }
    return { kind: 'commit', commitish };
  }

  return { kind: 'commit', commitish: raw };
}

function extractLastTrailerValue(message: string, key: 'Entire-Checkpoint' | 'Entire-Attribution'): string | null {
  const lines = message.split(/\r?\n/);
  let found: string | null = null;

  for (const line of lines) {
    const match = line.match(/^([A-Za-z0-9-]+):\s*(.*)$/);
    if (!match) {
      continue;
    }

    if (match[1].toLowerCase() === key.toLowerCase()) {
      found = match[2].trim();
    }
  }

  return found;
}

export function extractEntireSessionId(entireAttribution: string | null): string | null {
  if (!entireAttribution) {
    return null;
  }

  const value = entireAttribution.trim();
  if (!value) {
    return null;
  }

  try {
    const parsed = JSON.parse(value) as unknown;
    if (parsed && typeof parsed === 'object') {
      const obj = parsed as Record<string, unknown>;
      const direct = obj.sessionId;
      if (typeof direct === 'string' && direct.trim()) {
        return direct.trim();
      }

      const snake = obj.session_id;
      if (typeof snake === 'string' && snake.trim()) {
        return snake.trim();
      }
    }
  } catch {
    // Not JSON, continue with regex extraction.
  }

  const kvMatch = value.match(/session[_-]?id\s*[:=]\s*([A-Za-z0-9_-]+)/i);
  if (kvMatch) {
    return kvMatch[1];
  }

  return null;
}

export function parseCommitTrailers(message: string): ParsedTrailers {
  const checkpointIdRaw = extractLastTrailerValue(message, 'Entire-Checkpoint');
  const checkpointId = checkpointIdRaw && isCheckpointId(checkpointIdRaw) ? checkpointIdRaw.toLowerCase() : null;
  const entireAttribution = extractLastTrailerValue(message, 'Entire-Attribution');

  return {
    checkpointId,
    entireAttribution,
    entireSessionId: extractEntireSessionId(entireAttribution),
  };
}

export function resolveCheckpointFromHistory(
  checkpointId: string,
  commitsInPriorityOrder: CommitHistoryEntry[]
): CheckpointResolutionFromHistory {
  const normalizedCheckpointId = checkpointId.toLowerCase();
  const matches: Array<{ sha: string; trailers: ParsedTrailers }> = [];

  for (const commit of commitsInPriorityOrder) {
    const trailers = parseCommitTrailers(commit.message);
    if (trailers.checkpointId === normalizedCheckpointId) {
      matches.push({ sha: commit.sha, trailers });
    }
  }

  if (matches.length === 0) {
    throw new Error(`No commit found with trailer Entire-Checkpoint: ${normalizedCheckpointId}`);
  }

  return {
    selected: matches[0],
    matchCount: matches.length,
    matchedShas: matches.map((match) => match.sha),
  };
}

export function selectProjectRoot(candidates: ProjectRootCandidate[]): ProjectRootCandidate {
  if (candidates.length === 0) {
    throw new Error('No deployable project root detected. Pass --project-root to choose a directory.');
  }

  if (candidates.length > 1) {
    const details = candidates.map((candidate) => `${candidate.path} (${candidate.signals.join(', ')})`).join('; ');
    throw new Error(
      `Multiple deployable project roots detected. Pass --project-root to disambiguate. Candidates: ${details}`
    );
  }

  return candidates[0];
}

function getDirectory(path: string): string {
  const normalized = path.replace(/\\/g, '/').replace(/^\.\//, '');
  if (!normalized.includes('/')) {
    return '.';
  }

  return normalized.slice(0, normalized.lastIndexOf('/'));
}

function getFileName(path: string): string {
  const normalized = path.replace(/\\/g, '/');
  const parts = normalized.split('/');
  return parts[parts.length - 1];
}

function hasBuildScript(packageJsonContent: string | undefined): boolean {
  if (!packageJsonContent) {
    return false;
  }

  try {
    const parsed = JSON.parse(packageJsonContent) as unknown;
    if (!parsed || typeof parsed !== 'object') {
      return false;
    }

    const scripts = (parsed as Record<string, unknown>).scripts;
    if (!scripts || typeof scripts !== 'object') {
      return false;
    }

    return typeof (scripts as Record<string, unknown>).build === 'string';
  } catch {
    return false;
  }
}

export function detectProjectRootCandidates(treeFiles: TreeFileEntry[]): ProjectRootCandidate[] {
  const signalMap = new Map<string, Set<string>>();

  for (const file of treeFiles) {
    const fileName = getFileName(file.path);
    const directory = getDirectory(file.path);

    const signals = signalMap.get(directory) ?? new Set<string>();

    if (fileName === 'package.json') {
      signals.add('package_json');
      if (hasBuildScript(file.content)) {
        signals.add('build_script');
      }
    }

    if (LOCKFILE_NAMES.has(fileName)) {
      signals.add('lockfile');
    }

    if (FRAMEWORK_CONFIG_REGEXES.some((regex) => regex.test(fileName))) {
      signals.add('framework_config');
    }

    if (signals.size > 0) {
      signalMap.set(directory, signals);
    }
  }

  return Array.from(signalMap.entries())
    .filter(([, signals]) => signals.size >= 2)
    .map(([path, signals]) => ({
      path,
      signals: Array.from(signals).sort((a, b) => a.localeCompare(b)),
    }))
    .sort((a, b) => a.path.localeCompare(b.path));
}

import { runCheckpointResolverTests } from './checkpoint/resolver.test.js';
import { runCheckpointEnvTests } from './checkpoint/env.test.js';
import { runCheckpointOptionsTests } from '../commands/deploy/checkpoint-options.test.js';
import { runCheckpointGitTests } from './checkpoint/git.test.js';

type TestCase = {
  name: string;
  run: () => void | Promise<void>;
};

const TEST_CASES: TestCase[] = [
  { name: 'checkpoint-resolver', run: runCheckpointResolverTests },
  { name: 'checkpoint-env', run: runCheckpointEnvTests },
  { name: 'checkpoint-git', run: runCheckpointGitTests },
  { name: 'checkpoint-options', run: runCheckpointOptionsTests },
];

async function main(): Promise<void> {
  let failed = 0;

  for (const testCase of TEST_CASES) {
    try {
      await testCase.run();
      console.log(`PASS ${testCase.name}`);
    } catch (error) {
      failed += 1;
      const message = error instanceof Error ? error.stack || error.message : String(error);
      console.error(`FAIL ${testCase.name}`);
      console.error(message);
    }
  }

  if (failed > 0) {
    process.exit(1);
  }

  console.log(`All tests passed (${TEST_CASES.length})`);
}

main().catch((error) => {
  const message = error instanceof Error ? error.stack || error.message : String(error);
  console.error('Test runner crashed');
  console.error(message);
  process.exit(1);
});

