       id,
       prompt,
       model,
       status,
       phase,
       source_type,
       checkpoint_id,
       commit_sha,
       source_ref,
       source_bundle_key,
       source_bundle_sha256,
       source_bundle_bytes
     )
     VALUES (?, ?, 'checkpoint', ?, ?, 'checkpoint', ?, ?, ?, ?, ?, ?)`
  )
    .bind(
      jobId,
      checkpointPrompt(metadata.source.checkpointId, metadata.source.commitSha),
      'queued' satisfies JobStatus,
      'queued' satisfies JobPhase,
      metadata.source.checkpointId,
      metadata.source.commitSha,
      metadata.source.ref ?? null,
      sourceBundleKey,
      sourceBundleSha256,
      sourceBundleBytes
    )
