      env,
      jobId,
      parsed.metadata,
      sourceBundleKey,
      parsed.bundleSha256,
      parsed.bundleBytes
    );
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return new Response(JSON.stringify({ error: `Failed to create checkpoint job: ${message}` }), {
      status: 500,
      headers: { 'Content-Type': 'application/json', ...corsHeaders },
    });
  }

