export type JobPhase =
  | 'queued'
  | 'planning'
  | 'generating'
  | 'building'
  | 'repairing'
  | 'validating'
  | 'deploying'
  | 'completed'
  | 'failed'
  | 'cancelled';

// Job record from D1 database
export interface JobRecord {
  id: string;
  prompt: string;
  model: string;
  status: JobStatus;
  phase?: JobPhase;
  created_at: string;
  started_at: string | null;
  completed_at: string | null;
  cancel_requested_at?: string | null;
  cancelled_at?: string | null;
  preview_url: string | null;
  deployed_url: string | null;
  code_url?: string | null;
  code_zip_url?: string | null;
  error_message: string | null;
  error_code?: string | null;
  file_count: number | null;
  current_attempt?: number;
  retry_count?: number;

  source_type?: string | null;
  checkpoint_id?: string | null;
  commit_sha?: string | null;
  source_ref?: string | null;
  source_bundle_key?: string | null;
  source_bundle_sha256?: string | null;
  source_bundle_bytes?: number | null;
}

// Job response for API (camelCase)
export interface JobResponse {
  id: string;
  prompt: string;
  model: string;
  status: JobStatus;
  phase: JobPhase;
  createdAt: string;
  startedAt: string | null;
  completedAt: string | null;
  cancelRequestedAt?: string | null;
  cancelledAt?: string | null;
  previewUrl: string | null;
  deployedUrl: string | null;
  codeUrl?: string | null;
  codeZipUrl?: string | null;
  errorMessage: string | null;
  errorCode?: string | null;
  fileCount: number | null;
  currentAttempt?: number;
  retryCount?: number;

  sourceType?: string | null;
  checkpointId?: string | null;
  commitSha?: string | null;
  sourceRef?: string | null;
  sourceBundleKey?: string | null;
  sourceBundleSha256?: string | null;
  sourceBundleBytes?: number | null;
}

// Job list item (lightweight for listing)
export interface JobListItem {
  id: string;
  prompt: string;
  model: string;
  status: JobStatus;
  phase?: JobPhase;
  createdAt: string;
  deployedUrl: string | null;
}

export interface RuntimeFlags {
  v2Enabled: boolean;
  v2CodeBrowserEnabled: boolean;
  maxAttempts: number;
  attemptTimeoutMs: number;
  totalTimeoutMs: number;
  idempotencyTtlHours: number;
  maxRepairCycles: number;
  lintBlocking: boolean;
  testBlocking: boolean;
  safeInstallIgnoreScripts: boolean;
  autoInstallScriptsFallback: boolean;
  rawRetentionDays: number;
  summaryRetentionDays: number;
}

export interface GeneratedFile {
  path: string;
  content: string;
}

export interface GeneratedCode {
  files: GeneratedFile[];
}

// SSE Event types
export type SSEEvent =
  | { type: 'job_created'; jobId: string }
  | { type: 'generating' }
  | { type: 'generated'; fileCount: number }
  | { type: 'scaffolding' }
  | { type: 'writing' }
  | { type: 'installing' }
  | { type: 'building' }
  | { type: 'starting' }
  | { type: 'preview_ready'; previewUrl: string }
  | { type: 'deploying' }
  | { type: 'deploy_warning'; message: string }
  | { type: 'deployed'; deployedUrl: string }
  | {
      type: 'complete';
      previewUrl: string;
      deployedUrl: string;
      isPreviewFallback?: boolean;
      metrics: BuildMetrics;
    }
  | { type: 'error'; message: string };

// OpenRouter types
export interface OpenRouterMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

export interface OpenRouterRequest {
  model: string;
  messages: OpenRouterMessage[];
  max_tokens?: number;
  temperature?: number;
}

export interface OpenRouterResponse {
  id: string;
  choices: {
    message: {
      role: string;
      content: string;
    };
    finish_reason: string;
  }[];
  usage: {
    prompt_tokens: number;
    completion_tokens: number;
    total_tokens: number;
    cost?: number; // May not be returned by all providers
  };
}

// OpenRouter Generation API response (for querying cost after completion)
export interface OpenRouterGenerationResponse {
  data: {
    id: string;
    total_cost: number; // Cost in USD
    native_tokens_prompt: number | null;
    native_tokens_completion: number | null;
    latency: number | null;
  };
}

// Build metrics returned to CLI
// NOTE: This interface is duplicated in packages/cli/src/lib/types.ts - keep them in sync
export interface BuildMetrics {
  id: string;
  prompt: string;
  model: string;
  promptTokens: number;
  completionTokens: number;
  totalTokens: number;
  cost: number;
  llmLatencyMs: number;
  filesGenerated: number;
  linesOfCode: number;
  buildSuccess: boolean;
  deploySuccess: boolean;
  deployError?: string;
  installDurationMs: number;
  buildDurationMs: number;
  deployDurationMs: number;
  totalDurationMs: number;
  deployedUrl: string;
  startedAt: string;
  completedAt: string;
}

