}

function normalizeRelativePath(path: string): string {
  const trimmed = path.trim();
  if (!trimmed || trimmed === '.') {
    return '.';
  }

  const noLeadingDot = trimmed.replace(/^\.\//, '');
  const normalized = noLeadingDot.replace(/\\/g, '/').replace(/\/+$/, '');
  return normalized || '.';
