function readLocalEnvFiles(projectRoot: string, explicitEnvFiles: string[]): {
  loadedFiles: string[];
  values: Map<string, string>;
} {
  const cwd = process.cwd();
  const projectRootAbsolute = resolve(cwd, projectRoot);
  const directories = new Set<string>([cwd, projectRootAbsolute]);
  const discoveredFiles = new Set<string>();

  for (const directory of directories) {
    let entries: string[] = [];
    try {
      entries = readdirSync(directory);
    } catch {
