function parseArgs(args: string[]): {
  command: string | null;
  flags: Record<string, string | boolean | string[]>;
  positional: string[];
} {
  const flags: Record<string, string | boolean | string[]> = {};
  const positional: string[] = [];
  let command: string | null = null;

  const appendFlagValue = (key: string, value: string | boolean): void => {
    const existing = flags[key];
    if (existing === undefined) {
      flags[key] = value;
      return;
    }

    if (typeof value === 'boolean') {
      flags[key] = value;
      return;
    }

    if (Array.isArray(existing)) {
      existing.push(value);
      flags[key] = existing;
      return;
    }

    if (typeof existing === 'string') {
      flags[key] = [existing, value];
      return;
    }

    flags[key] = value;
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];

    if (arg.startsWith('--')) {
      const key = arg.slice(2);
      // Check if next arg is a value (not another flag)
      if (i + 1 < args.length && !args[i + 1].startsWith('-')) {
        appendFlagValue(key, args[++i]);
      } else {
        appendFlagValue(key, true);
      }
    } else if (arg.startsWith('-')) {
      const key = arg.slice(1);
      // Handle short flags
      if (key === 'm' && i + 1 < args.length && !args[i + 1].startsWith('-')) {
        appendFlagValue('model', args[++i]);
      } else if (key === 'h') {
        appendFlagValue('help', true);
      } else if (key === 'v') {
        appendFlagValue('version', true);
      } else {
        appendFlagValue(key, true);
      }
    } else if (!command) {
      command = arg;
    } else {
      positional.push(arg);
    }
  }

  return { command, flags, positional };
}

