    assert.equal(preflight.values.get('API_BASE_URL')?.source, 'explicit');
    assert.equal(preflight.values.get('SESSION_SECRET')?.source, 'explicit');
    assert.equal(preflight.values.get('CF_ACCOUNT_ID')?.source, 'local');
