function phaseFromStatus(status: JobStatus): JobPhase {
  switch (status) {
    case 'queued':
      return 'queued';
    case 'running':
      return 'building';
    case 'completed':
      return 'completed';
    case 'failed':
      return 'failed';
    case 'cancelled':
      return 'cancelled';
  }
}

/**
 * Generate a unique job ID
 */
export function generateJobId(): string {
  const chars = 'REDACTED';
  let id = '';
  for (let i = 0; i < 8; i++) {
    id += chars[Math.floor(Math.random() * chars.length)];
  }
  return `job_${id}`;
}

/**
 * Convert snake_case DB record to camelCase API response
 */
function toJobResponse(record: JobRecord): JobResponse {
  const phase = record.phase ?? phaseFromStatus(record.status);

  return {
    id: record.id,
    prompt: record.prompt,
    model: record.model,
    status: record.status,
    phase,
    createdAt: record.created_at,
