    const inserts: unknown[][] = [];

    const env = {
      SOURCE_BUNDLES: {
        async put(key: string, value: unknown): Promise<void> {
          const bytes = value instanceof ArrayBuffer ? value.byteLength : 0;
          puts.push({ key, bytes });
        },
      },
      DB: {
        prepare() {
          return {
            bind(...values: unknown[]) {
              inserts.push(values);
              return {
                async first<T>() {
                  return {
                    id: values[0],
                    prompt: values[1],
                    model: 'checkpoint',
                    status: 'queued',
                    phase: 'queued',
                    created_at: '2026-03-06T10:00:00.000Z',
                    started_at: null,
                    completed_at: null,
                    cancel_requested_at: null,
                    cancelled_at: null,
                    preview_url: null,
                    deployed_url: null,
                    code_url: null,
