export function runCheckpointBuildPlanTests(): void {
  {
    const pm = detectPackageManager(['package-lock.json']);
    assert.equal(pm, 'npm');
  }

  {
    const pm = detectPackageManager(['bun.lockb']);
    assert.equal(pm, 'bun');
  }

  assert.throws(() => detectPackageManager(['pnpm-lock.yaml']), /not supported/i);
  assert.throws(() => detectPackageManager([]), /No lockfile found/i);

  {
    const dir = resolveProjectDirectory('/root/source', 'apps/web');
    assert.equal(dir, '/root/source/apps/web');
  }

  {
    const dir = resolveProjectDirectory('/root/source', '.');
    assert.equal(dir, '/root/source');
  }

  {
    const plan = buildCheckpointPlan({
      packageManager: 'npm',
      scripts: { build: 'vite build', test: 'vitest', lint: 'eslint .' },
      runTestsIfPresent: true,
      runLintIfPresent: false,
    });

    assert.equal(plan.install.command, 'npm ci --ignore-scripts --no-audit --no-fund');
    assert.equal(plan.build?.command, 'npm run build');
    assert.equal(plan.test?.command, 'npm run test');
    assert.equal(plan.lint, null);
  }

  {
    const plan = buildCheckpointPlan({
      packageManager: 'bun',
      scripts: { build: 'vite build', test: 'vitest', lint: 'eslint .' },
      runTestsIfPresent: false,
      runLintIfPresent: true,
    });

    assert.equal(plan.install.command, 'bun install --frozen-lockfile --ignore-scripts');
    assert.equal(plan.build?.command, 'bun run build');
    assert.equal(plan.test, null);
    assert.equal(plan.lint?.command, 'bun run lint');
  }

  {
    const plan = buildCheckpointPlan({
      packageManager: 'npm',
      scripts: {},
      runTestsIfPresent: true,
      runLintIfPresent: true,
    });

    assert.equal(plan.build, null);
    assert.equal(plan.test, null);
    assert.equal(plan.lint, null);
  }

  const unsupported: PackageManager = 'npm';
  assert.equal(unsupported, 'npm');
}

export type PackageManager = 'npm' | 'bun';

export interface ScriptMap {
  [name: string]: string;
}

export interface CheckpointCommand {
  name: string;
  command: string;
}

export interface CheckpointBuildPlan {
  install: CheckpointCommand;
  build: CheckpointCommand | null;
  test: CheckpointCommand | null;
  lint: CheckpointCommand | null;
}

export function resolveProjectDirectory(sourceRoot: string, projectRoot: string | null | undefined): string {
  if (!projectRoot || projectRoot === '.') {
    return sourceRoot;
  }

  return `${sourceRoot}/${projectRoot}`;
}

export function detectPackageManager(lockfiles: string[]): PackageManager {
  const set = new Set(lockfiles);

  if (set.has('bun.lock') || set.has('bun.lockb')) {
    return 'bun';
  }

  if (set.has('package-lock.json')) {
    return 'npm';
  }

  if (set.has('pnpm-lock.yaml')) {
    throw new Error('pnpm lockfile detected but pnpm is not supported in sandbox yet');
  }

  if (set.has('yarn.lock')) {
    throw new Error('yarn lockfile detected but yarn is not supported in sandbox yet');
  }

  throw new Error('No lockfile found. Checkpoint deploy requires a lockfile for deterministic install.');
}

function installCommandFor(pm: PackageManager): string {
  if (pm === 'bun') {
    return 'bun install --frozen-lockfile --ignore-scripts';
  }

  return 'npm ci --ignore-scripts --no-audit --no-fund';
}

function scriptCommandFor(pm: PackageManager, scriptName: string): string {
  if (pm === 'bun') {
    return `bun run ${scriptName}`;
  }

  return `npm run ${scriptName}`;
}

export function buildCheckpointPlan(input: {
  packageManager: PackageManager;
  scripts: ScriptMap;
  runTestsIfPresent: boolean;
  runLintIfPresent: boolean;
}): CheckpointBuildPlan {
  const hasBuildScript = typeof input.scripts.build === 'string';
  const hasTestScript = typeof input.scripts.test === 'string';
  const hasLintScript = typeof input.scripts.lint === 'string';

  return {
    install: {
      name: 'install',
      command: installCommandFor(input.packageManager),
    },
    build: hasBuildScript
      ? {
          name: 'build',
          command: scriptCommandFor(input.packageManager, 'build'),
        }
      : null,
    test:
      input.runTestsIfPresent && hasTestScript
        ? {
            name: 'test',
            command: scriptCommandFor(input.packageManager, 'test'),
          }
        : null,
    lint:
      input.runLintIfPresent && hasLintScript
        ? {
            name: 'lint',
            command: scriptCommandFor(input.packageManager, 'lint'),
          }
        : null,
  };
}

import { getSandbox, type Sandbox } from '@cloudflare/sandbox';
import { getJob, updateJobStatus } from './db.js';
import {
  buildCheckpointPlan,
  detectPackageManager,
  resolveProjectDirectory,
} from './checkpoint-build-plan.js';
import type { Env, JobPhase, JobResponse } from '../types.js';

const SOURCE_ROOT = '/root/checkpoint-source';
const BUNDLE_PATH = '/tmp/source.tar.gz';
const BUNDLE_BASE64_PATH = '/tmp/source.tar.gz.base64';
const INSTALL_TIMEOUT_MS = 8 * 60 * 1000;
const BUILD_TIMEOUT_MS = 8 * 60 * 1000;
const VALIDATION_TIMEOUT_MS = 8 * 60 * 1000;

const LOCKFILE_CANDIDATES = ['bun.lock', 'bun.lockb', 'package-lock.json', 'pnpm-lock.yaml', 'yarn.lock'];

function shellQuote(value: string): string {
  return `'${value.replace(/'/g, `'"'"'`)}'`;
}

async function fileExists(
  sandbox: ReturnType<typeof getSandbox>,
  path: string
): Promise<boolean> {
  const result = await sandbox.exec(`test -f ${shellQuote(path)} && echo yes || echo no`);
  return result.stdout.trim() === 'yes';
}

async function detectLockfiles(
  sandbox: ReturnType<typeof getSandbox>,
  projectDir: string
): Promise<string[]> {
  const lockfiles: string[] = [];

  for (const lockfile of LOCKFILE_CANDIDATES) {
    if (await fileExists(sandbox, `${projectDir}/${lockfile}`)) {
      lockfiles.push(lockfile);
    }
  }

  return lockfiles;
}

async function runSandboxStep(
  sandbox: ReturnType<typeof getSandbox>,
  projectDir: string,
  command: string,
  timeout: number,
  phase: JobPhase,
  env: Env,
  jobId: string
): Promise<void> {
  await updateJobStatus(env.DB, jobId, 'running', { phase });

  const result = await sandbox.exec(`cd ${shellQuote(projectDir)} && ${command}`, { timeout });
  if (result.exitCode !== 0) {
    const output = [result.stdout, result.stderr].filter(Boolean).join('\n');
    throw new Error(`${phase} step failed (exit ${result.exitCode}): ${output || 'No output'}`);
  }
}

function toBase64(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer);
  let binary = '';
  for (const byte of bytes) {
    binary += String.fromCharCode(byte);
  }

  return btoa(binary);
}

function resolveValidationFlags(job: JobResponse): {
  runTestsIfPresent: boolean;
  runLintIfPresent: boolean;
} {
  return {
    runTestsIfPresent: job.buildRunTestsIfPresent ?? true,
    runLintIfPresent: job.buildRunLintIfPresent ?? true,
  };
}

export async function executeCheckpointJob(env: Env, job: JobResponse): Promise<void> {
  if (!env.SOURCE_BUNDLES) {
    throw new Error('SOURCE_BUNDLES binding is not configured');
  }

  if (!job.sourceBundleKey) {
    throw new Error('Checkpoint job is missing source bundle key');
  }

  const bundleObject = await env.SOURCE_BUNDLES.get(job.sourceBundleKey);
  if (!bundleObject) {
    throw new Error(`Source bundle not found in R2: ${job.sourceBundleKey}`);
  }

  const sourceBytes = await bundleObject.arrayBuffer();
  const sourceBase64 = toBase64(sourceBytes);
  const sandboxId = `checkpoint-${job.id}-${Date.now()}`;
  const sandbox = getSandbox(env.Sandbox as DurableObjectNamespace<Sandbox>, sandboxId);

  await updateJobStatus(env.DB, job.id, 'running', {
    phase: 'building',
    started_at: job.startedAt ?? new Date().toISOString(),
  });

  try {
    await sandbox.exec(`rm -rf ${shellQuote(SOURCE_ROOT)} && mkdir -p ${shellQuote(SOURCE_ROOT)}`);
    await sandbox.writeFile(BUNDLE_BASE64_PATH, sourceBase64);

    await runSandboxStep(
      sandbox,
      SOURCE_ROOT,
      `base64 -d ${shellQuote(BUNDLE_BASE64_PATH)} > ${shellQuote(BUNDLE_PATH)} && tar -xzf ${shellQuote(BUNDLE_PATH)} -C ${shellQuote(SOURCE_ROOT)}`,
      INSTALL_TIMEOUT_MS,
      'building',
      env,
      job.id
    );

    const projectDir = resolveProjectDirectory(SOURCE_ROOT, job.sourceProjectRoot ?? '.');
    const projectDirCheck = await sandbox.exec(`test -d ${shellQuote(projectDir)} && echo yes || echo no`);
    if (projectDirCheck.stdout.trim() !== 'yes') {
      throw new Error(`Resolved project root is not a directory: ${job.sourceProjectRoot ?? '.'}`);
    }

    const packageJsonPath = `${projectDir}/package.json`;
    const hasPackageJson = await fileExists(sandbox, packageJsonPath);

    if (hasPackageJson) {
      const packageJsonRaw = await sandbox.readFile(packageJsonPath, { encoding: 'utf8' });
      const packageJson = JSON.parse((packageJsonRaw as { content: string }).content) as {
        scripts?: Record<string, string>;
      };
      const lockfiles = await detectLockfiles(sandbox, projectDir);
      const packageManager = detectPackageManager(lockfiles);
      const flags = resolveValidationFlags(job);
      const plan = buildCheckpointPlan({
        packageManager,
        scripts: packageJson.scripts ?? {},
        runTestsIfPresent: flags.runTestsIfPresent,
        runLintIfPresent: flags.runLintIfPresent,
      });

      await runSandboxStep(
        sandbox,
        projectDir,
        plan.install.command,
        INSTALL_TIMEOUT_MS,
        'building',
        env,
        job.id
      );

      if (plan.build) {
        await runSandboxStep(
          sandbox,
          projectDir,
          plan.build.command,
          BUILD_TIMEOUT_MS,
          'building',
          env,
          job.id
        );
      }

      if (plan.test) {
        await runSandboxStep(
          sandbox,
          projectDir,
          plan.test.command,
          VALIDATION_TIMEOUT_MS,
          'validating',
          env,
          job.id
        );
      }

      if (plan.lint) {
        await runSandboxStep(
          sandbox,
          projectDir,
          plan.lint.command,
          VALIDATION_TIMEOUT_MS,
          'validating',
          env,
          job.id
        );
      }
    }

    await updateJobStatus(env.DB, job.id, 'completed', {
      phase: 'completed',
      completed_at: new Date().toISOString(),
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    await updateJobStatus(env.DB, job.id, 'failed', {
      phase: 'failed',
      completed_at: new Date().toISOString(),
      error_message: message,
    });
    throw error;
  } finally {
    try {
      await sandbox.destroy();
    } catch {
      // Best-effort cleanup.
    }
  }
}

export async function loadCheckpointJob(env: Env, jobId: string): Promise<JobResponse> {
  const job = await getJob(env.DB, jobId);
  if (!job) {
    throw new Error(`Job not found: ${jobId}`);
  }

  return job;
}

