import { getSandbox, type Sandbox } from '@cloudflare/sandbox';
import { getJob, updateJobStatus } from './db.js';
import {
  buildCheckpointPlan,
  detectPackageManager,
  resolveProjectDirectory,
} from './checkpoint-build-plan.js';
import type { Env, JobPhase, JobResponse } from '../types.js';

const SOURCE_ROOT = '/root/checkpoint-source';
const BUNDLE_PATH = '/tmp/source.tar.gz';
const INSTALL_TIMEOUT_MS = 8 * 60 * 1000;
const BUILD_TIMEOUT_MS = 8 * 60 * 1000;
const VALIDATION_TIMEOUT_MS = 8 * 60 * 1000;

const LOCKFILE_CANDIDATES = ['bun.lock', 'bun.lockb', 'package-lock.json', 'pnpm-lock.yaml', 'yarn.lock'];

function shellQuote(value: string): string {
  return `'${value.replace(/'/g, `'"'"'`)}'`;
}

async function fileExists(
  sandbox: ReturnType<typeof getSandbox>,
  path: string
): Promise<boolean> {
  const result = await sandbox.exec(`test -f ${shellQuote(path)} && echo yes || echo no`);
  return result.stdout.trim() === 'yes';
}

async function detectLockfiles(
  sandbox: ReturnType<typeof getSandbox>,
  projectDir: string
): Promise<string[]> {
  const lockfiles: string[] = [];

  for (const lockfile of LOCKFILE_CANDIDATES) {
    if (await fileExists(sandbox, `${projectDir}/${lockfile}`)) {
      lockfiles.push(lockfile);
    }
  }

  return lockfiles;
}

async function runSandboxStep(
  sandbox: ReturnType<typeof getSandbox>,
  projectDir: string,
  command: string,
  timeout: number,
  phase: JobPhase,
  env: Env,
  jobId: string
): Promise<void> {
  await updateJobStatus(env.DB, jobId, 'running', { phase });

  const result = await sandbox.exec(`cd ${shellQuote(projectDir)} && ${command}`, { timeout });
  if (result.exitCode !== 0) {
    const output = [result.stdout, result.stderr].filter(Boolean).join('\n');
    throw new Error(`${phase} step failed (exit ${result.exitCode}): ${output || 'No output'}`);
  }
}

function resolveValidationFlags(job: JobResponse): {
  runTestsIfPresent: boolean;
  runLintIfPresent: boolean;
} {
  return {
    runTestsIfPresent: job.buildRunTestsIfPresent ?? true,
    runLintIfPresent: job.buildRunLintIfPresent ?? true,
  };
}

export async function executeCheckpointJob(env: Env, job: JobResponse): Promise<void> {
  if (!env.SOURCE_BUNDLES) {
    throw new Error('SOURCE_BUNDLES binding is not configured');
  }

  if (!job.sourceBundleKey) {
    throw new Error('Checkpoint job is missing source bundle key');
  }

  const bundleObject = await env.SOURCE_BUNDLES.get(job.sourceBundleKey);
  if (!bundleObject) {
    throw new Error(`Source bundle not found in R2: ${job.sourceBundleKey}`);
  }

  const sourceBytes = await bundleObject.arrayBuffer();
  const sandboxId = `checkpoint-${job.id}-${Date.now()}`;
  const sandbox = getSandbox(env.Sandbox as DurableObjectNamespace<Sandbox>, sandboxId);

  await updateJobStatus(env.DB, job.id, 'running', {
    phase: 'building',
    started_at: job.startedAt ?? new Date().toISOString(),
  });

  try {
    await sandbox.exec(`rm -rf ${shellQuote(SOURCE_ROOT)} && mkdir -p ${shellQuote(SOURCE_ROOT)}`);
    await sandbox.writeFile(BUNDLE_PATH, sourceBytes);

    await runSandboxStep(
      sandbox,
      SOURCE_ROOT,
      `tar -xzf ${shellQuote(BUNDLE_PATH)} -C ${shellQuote(SOURCE_ROOT)}`,
      INSTALL_TIMEOUT_MS,
      'building',
      env,
      job.id
    );

    const projectDir = resolveProjectDirectory(SOURCE_ROOT, job.sourceProjectRoot ?? '.');
    const projectDirCheck = await sandbox.exec(`test -d ${shellQuote(projectDir)} && echo yes || echo no`);
    if (projectDirCheck.stdout.trim() !== 'yes') {
      throw new Error(`Resolved project root is not a directory: ${job.sourceProjectRoot ?? '.'}`);
    }

    const packageJsonPath = `${projectDir}/package.json`;
    const hasPackageJson = await fileExists(sandbox, packageJsonPath);

    if (hasPackageJson) {
      const packageJsonRaw = await sandbox.readFile(packageJsonPath, { encoding: 'utf8' });
      const packageJson = JSON.parse(packageJsonRaw as string) as { scripts?: Record<string, string> };
      const lockfiles = await detectLockfiles(sandbox, projectDir);
      const packageManager = detectPackageManager(lockfiles);
      const flags = resolveValidationFlags(job);
      const plan = buildCheckpointPlan({
        packageManager,
        scripts: packageJson.scripts ?? {},
        runTestsIfPresent: flags.runTestsIfPresent,
        runLintIfPresent: flags.runLintIfPresent,
      });

      await runSandboxStep(
        sandbox,
        projectDir,
        plan.install.command,
        INSTALL_TIMEOUT_MS,
        'building',
        env,
        job.id
      );

      if (plan.build) {
        await runSandboxStep(
          sandbox,
          projectDir,
          plan.build.command,
          BUILD_TIMEOUT_MS,
          'building',
          env,
          job.id
        );
      }

      if (plan.test) {
        await runSandboxStep(
          sandbox,
          projectDir,
          plan.test.command,
          VALIDATION_TIMEOUT_MS,
          'validating',
          env,
          job.id
        );
      }

      if (plan.lint) {
        await runSandboxStep(
          sandbox,
          projectDir,
          plan.lint.command,
          VALIDATION_TIMEOUT_MS,
          'validating',
          env,
          job.id
        );
      }
    }

    await updateJobStatus(env.DB, job.id, 'completed', {
      phase: 'completed',
      completed_at: new Date().toISOString(),
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    await updateJobStatus(env.DB, job.id, 'failed', {
      phase: 'failed',
      completed_at: new Date().toISOString(),
      error_message: message,
    });
    throw error;
  } finally {
    try {
      await sandbox.destroy();
    } catch {
      // Best-effort cleanup.
    }
  }
}

export async function loadCheckpointJob(env: Env, jobId: string): Promise<JobResponse> {
  const job = await getJob(env.DB, jobId);
  if (!job) {
    throw new Error(`Job not found: ${jobId}`);
  }

  return job;
}

