    metadata,
    bundle: bundleField,
    bundleBytes: bundleArrayBuffer.byteLength,
    bundleSha256,
    bundleArrayBuffer,
  };
}

export function ensureRunnableCheckpointJob(job: {
  id: string;
  status: string;
  sourceType?: string | null;
  sourceBundleKey?: string | null;
  commitSha?: string | null;
  sourceProjectRoot?: string | null;
  buildRunTestsIfPresent?: boolean | null;
  buildRunLintIfPresent?: boolean | null;
}): RunnableCheckpointJob {
  if (job.sourceType !== 'checkpoint') {
    throw new Error(`Job ${job.id} is not a checkpoint job`);
  }

  if (!job.sourceBundleKey) {
    throw new Error(`Checkpoint job ${job.id} is missing source bundle key`);
  }

  if (!job.commitSha) {
    throw new Error(`Checkpoint job ${job.id} is missing commit SHA`);
  }

  return {
    id: job.id,
    status: job.status,
    sourceType: job.sourceType,
    sourceBundleKey: job.sourceBundleKey,
    commitSha: job.commitSha,
    sourceProjectRoot: job.sourceProjectRoot ?? null,
    buildRunTestsIfPresent: job.buildRunTestsIfPresent ?? null,
    buildRunLintIfPresent: job.buildRunLintIfPresent ?? null,
  };
}

function checkpointPrompt(checkpointId: string | null, commitSha: string): string {
  if (checkpointId) {
    return `Deploy checkpoint ${checkpointId}`;
  }

  return `Deploy commit ${commitSha.slice(0, 12)}`;
}

