      jobId,
      status: 'queued',
      phase: 'queued',
      eventsUrl: `/api/jobs/${jobId}/events`,
      jobUrl: `/api/jobs/${jobId}`,
    }),
    {
      status: 202,
      headers: { 'Content-Type': 'application/json', ...corsHeaders },
    }
  );
}

export async function handleRunCheckpointJob(jobId: string, env: Env): Promise<Response> {
  try {
    const job = await getJob(env.DB, jobId);
    if (!job) {
      return new Response(JSON.stringify({ error: `Job not found: ${jobId}` }), {
        status: 404,
        headers: { 'Content-Type': 'application/json', ...corsHeaders },
      });
    }

    ensureRunnableCheckpointJob({
      id: job.id,
      status: job.status,
      sourceType: job.sourceType,
      sourceBundleKey: job.sourceBundleKey,
      commitSha: job.commitSha,
      sourceProjectRoot: job.sourceProjectRoot,
      buildRunTestsIfPresent: job.buildRunTestsIfPresent,
      buildRunLintIfPresent: job.buildRunLintIfPresent,
    });

    if (job.status !== 'queued' && job.status !== 'failed') {
      return new Response(JSON.stringify({ error: `Checkpoint job ${jobId} is not runnable from status ${job.status}` }), {
        status: 409,
        headers: { 'Content-Type': 'application/json', ...corsHeaders },
      });
    }

    const { executeCheckpointJob } = await import('../lib/checkpoint-runner.js');
    await executeCheckpointJob(env, job);

    return new Response(JSON.stringify({
      jobId,
      status: 'completed',
      phase: 'completed',
      jobUrl: `/api/jobs/${jobId}`,
    }), {
      status: 200,
      headers: { 'Content-Type': 'application/json', ...corsHeaders },
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return new Response(JSON.stringify({ error: message }), {
      status: 400,
      headers: { 'Content-Type': 'application/json', ...corsHeaders },
    });
  }
}

