    form.set(
      'metadata',
      JSON.stringify({
        source: {
          type: 'checkpoint',
          checkpointId: '8a513f56ed70',
          commitSha: 'a'.repeat(40),
        },
        build: {
          runTestsIfPresent: true,
          runLintIfPresent: true,
