import { strict as assert } from 'assert';
import {
  buildCheckpointExecutionPlan,
  detectPackageManager,
  resolveProjectDir,
} from './checkpoint-plan.js';

export function runCheckpointPlanTests(): void {
  assert.equal(detectPackageManager(['package-lock.json']), 'npm');
  assert.equal(detectPackageManager(['bun.lockb']), 'bun');

  assert.throws(() => detectPackageManager(['pnpm-lock.yaml']), /pnpm lockfile/);
  assert.throws(() => detectPackageManager(['yarn.lock']), /yarn lockfile/);
  assert.throws(() => detectPackageManager([]), /No lockfile found/);

  assert.equal(resolveProjectDir('/root/source', '.'), '/root/source');
  assert.equal(resolveProjectDir('/root/source', 'apps/web'), '/root/source/apps/web');

  {
    const plan = buildCheckpointExecutionPlan({
      packageManager: 'npm',
      scripts: { build: 'vite build', test: 'vitest', lint: 'eslint .' },
      runTestsIfPresent: true,
      runLintIfPresent: false,
    });

    assert.equal(plan.install, 'npm ci --ignore-scripts --no-audit --no-fund');
    assert.equal(plan.build, 'npm run build');
    assert.equal(plan.test, 'npm run test');
    assert.equal(plan.lint, null);
  }

  {
    const plan = buildCheckpointExecutionPlan({
      packageManager: 'bun',
      scripts: { build: 'vite build' },
      runTestsIfPresent: true,
      runLintIfPresent: true,
    });

    assert.equal(plan.install, 'bun install --frozen-lockfile --ignore-scripts');
    assert.equal(plan.build, 'bun run build');
    assert.equal(plan.test, null);
    assert.equal(plan.lint, null);
  }
}

export type CheckpointPackageManager = 'npm' | 'bun';

export interface CheckpointExecutionPlan {
  install: string;
  build: string | null;
  test: string | null;
  lint: string | null;
}

export function resolveProjectDir(sourceRoot: string, sourceProjectRoot: string | null | undefined): string {
  if (!sourceProjectRoot || sourceProjectRoot === '.') {
    return sourceRoot;
  }

  return `${sourceRoot}/${sourceProjectRoot}`;
}

export function detectPackageManager(lockfiles: string[]): CheckpointPackageManager {
  const fileSet = new Set(lockfiles);

  if (fileSet.has('bun.lock') || fileSet.has('bun.lockb')) {
    return 'bun';
  }

  if (fileSet.has('package-lock.json')) {
    return 'npm';
  }

  if (fileSet.has('pnpm-lock.yaml')) {
    throw new Error('pnpm lockfile detected but pnpm is not supported yet for checkpoint execution');
  }

  if (fileSet.has('yarn.lock')) {
    throw new Error('yarn lockfile detected but yarn is not supported yet for checkpoint execution');
  }

  throw new Error('No lockfile found. Checkpoint execution requires lockfile-based deterministic install.');
}

function installCommand(packageManager: CheckpointPackageManager): string {
  if (packageManager === 'bun') {
    return 'bun install --frozen-lockfile --ignore-scripts';
  }

  return 'npm ci --ignore-scripts --no-audit --no-fund';
}

function runScriptCommand(packageManager: CheckpointPackageManager, scriptName: string): string {
  if (packageManager === 'bun') {
    return `bun run ${scriptName}`;
  }

  return `npm run ${scriptName}`;
}

export function buildCheckpointExecutionPlan(input: {
  packageManager: CheckpointPackageManager;
  scripts: Record<string, string>;
  runTestsIfPresent: boolean;
  runLintIfPresent: boolean;
}): CheckpointExecutionPlan {
  const hasBuild = typeof input.scripts.build === 'string';
  const hasTest = typeof input.scripts.test === 'string';
  const hasLint = typeof input.scripts.lint === 'string';

  return {
    install: installCommand(input.packageManager),
    build: hasBuild ? runScriptCommand(input.packageManager, 'build') : null,
    test: input.runTestsIfPresent && hasTest ? runScriptCommand(input.packageManager, 'test') : null,
    lint: input.runLintIfPresent && hasLint ? runScriptCommand(input.packageManager, 'lint') : null,
  };
}

import { getSandbox, type Sandbox } from '@cloudflare/sandbox';
import { getJob, updateJobStatus } from './db.js';
import {
  buildCheckpointExecutionPlan,
  detectPackageManager,
  resolveProjectDir,
} from './checkpoint-plan.js';
import type { Env, JobResponse, JobStatus } from '../types.js';

const SOURCE_ROOT = '/root/checkpoint-source';
const BUNDLE_BASE64_PATH = '/tmp/checkpoint-source.tar.gz.base64';
const BUNDLE_PATH = '/tmp/checkpoint-source.tar.gz';

const INSTALL_TIMEOUT_MS = 8 * 60 * 1000;
const BUILD_TIMEOUT_MS = 8 * 60 * 1000;
const VALIDATION_TIMEOUT_MS = 8 * 60 * 1000;

const LOCKFILE_NAMES = ['bun.lock', 'bun.lockb', 'package-lock.json', 'pnpm-lock.yaml', 'yarn.lock'];

class QueueRetryError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'QueueRetryError';
  }
}

function shellQuote(value: string): string {
  return `'${value.replace(/'/g, `'"'"'`)}'`;
}

function toBase64(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer);
  let binary = '';

  for (const byte of bytes) {
    binary += String.fromCharCode(byte);
  }

  return btoa(binary);
}

async function runCommand(
  sandbox: ReturnType<typeof getSandbox>,
  projectDir: string,
  command: string,
  timeout: number
): Promise<void> {
  const result = await sandbox.exec(`cd ${shellQuote(projectDir)} && ${command}`, { timeout });

  if (result.exitCode !== 0) {
    const output = [result.stdout, result.stderr].filter(Boolean).join('\n');
    throw new Error(`Command failed (${command}) with exit ${result.exitCode}: ${output || 'No output'}`);
  }
}

async function fileExists(
  sandbox: ReturnType<typeof getSandbox>,
  path: string
): Promise<boolean> {
  const result = await sandbox.exec(`test -f ${shellQuote(path)} && echo yes || echo no`);
  return result.stdout.trim() === 'yes';
}

async function listLockfiles(
  sandbox: ReturnType<typeof getSandbox>,
  projectDir: string
): Promise<string[]> {
  const files: string[] = [];

  for (const lockfile of LOCKFILE_NAMES) {
    if (await fileExists(sandbox, `${projectDir}/${lockfile}`)) {
      files.push(lockfile);
    }
  }

  return files;
}

async function readPackageScripts(
  sandbox: ReturnType<typeof getSandbox>,
  projectDir: string
): Promise<Record<string, string> | null> {
  const packageJsonPath = `${projectDir}/package.json`;
  const hasPackageJson = await fileExists(sandbox, packageJsonPath);

  if (!hasPackageJson) {
    return null;
  }

  const fileContent = (await sandbox.readFile(packageJsonPath, { encoding: 'utf8' })) as {
    content: string;
  };

  let parsed: unknown;
  try {
    parsed = JSON.parse(fileContent.content);
  } catch {
    throw new Error('Invalid package.json in checkpoint source');
  }

  if (!parsed || typeof parsed !== 'object') {
    return {};
  }

  const scripts = (parsed as { scripts?: unknown }).scripts;
  if (!scripts || typeof scripts !== 'object') {
    return {};
  }

  const normalized: Record<string, string> = {};
  for (const [key, value] of Object.entries(scripts as Record<string, unknown>)) {
    if (typeof value === 'string') {
      normalized[key] = value;
    }
  }

  return normalized;
}

function isRunnableStatus(status: JobStatus): boolean {
  return status === 'queued' || status === 'failed';
}

async function markFailed(db: D1Database, jobId: string, message: string): Promise<void> {
  await updateJobStatus(db, jobId, 'failed', {
    phase: 'failed',
    completed_at: new Date().toISOString(),
    error_message: message,
  });
}

async function executeCheckpointBuild(env: Env, job: JobResponse): Promise<void> {
  if (!env.SOURCE_BUNDLES) {
    throw new QueueRetryError('SOURCE_BUNDLES binding is not configured');
  }

  if (!job.sourceBundleKey || !job.commitSha) {
    throw new Error('Checkpoint job is missing source bundle metadata');
  }

  const bundle = await env.SOURCE_BUNDLES.get(job.sourceBundleKey);
  if (!bundle) {
    throw new Error(`Source bundle not found: ${job.sourceBundleKey}`);
  }

  const sourceBytes = await bundle.arrayBuffer();
  const encodedBundle = toBase64(sourceBytes);

  const sandboxId = `checkpoint-${job.id}-${Math.random().toString(36).slice(2, 10)}`;
  const sandbox = getSandbox(env.Sandbox as DurableObjectNamespace<Sandbox>, sandboxId);

  try {
    await sandbox.exec(`rm -rf ${shellQuote(SOURCE_ROOT)} && mkdir -p ${shellQuote(SOURCE_ROOT)}`);
    await sandbox.writeFile(BUNDLE_BASE64_PATH, encodedBundle);

    await sandbox.exec(
      `base64 -d ${shellQuote(BUNDLE_BASE64_PATH)} > ${shellQuote(BUNDLE_PATH)} && tar -xzf ${shellQuote(BUNDLE_PATH)} -C ${shellQuote(SOURCE_ROOT)}`,
      { timeout: INSTALL_TIMEOUT_MS }
    );

    const projectDir = resolveProjectDir(SOURCE_ROOT, job.sourceProjectRoot);
    const projectDirCheck = await sandbox.exec(`test -d ${shellQuote(projectDir)} && echo yes || echo no`);
    if (projectDirCheck.stdout.trim() !== 'yes') {
      throw new Error(`Resolved project root is not a directory: ${job.sourceProjectRoot ?? '.'}`);
    }

    const scripts = await readPackageScripts(sandbox, projectDir);
    if (scripts !== null) {
      const lockfiles = await listLockfiles(sandbox, projectDir);
      const packageManager = detectPackageManager(lockfiles);
      const plan = buildCheckpointExecutionPlan({
        packageManager,
        scripts,
        runTestsIfPresent: job.buildRunTestsIfPresent ?? true,
        runLintIfPresent: job.buildRunLintIfPresent ?? true,
      });

      await runCommand(sandbox, projectDir, plan.install, INSTALL_TIMEOUT_MS);

      if (plan.build) {
        await runCommand(sandbox, projectDir, plan.build, BUILD_TIMEOUT_MS);
      }

      if (plan.test || plan.lint) {
        await updateJobStatus(env.DB, job.id, 'running', { phase: 'validating' });
      }

      if (plan.test) {
        await runCommand(sandbox, projectDir, plan.test, VALIDATION_TIMEOUT_MS);
      }

      if (plan.lint) {
        await runCommand(sandbox, projectDir, plan.lint, VALIDATION_TIMEOUT_MS);
      }
    }

    await updateJobStatus(env.DB, job.id, 'completed', {
      phase: 'completed',
      completed_at: new Date().toISOString(),
    });
  } finally {
    try {
      await sandbox.destroy();
    } catch {
      // Best-effort cleanup.
    }
  }
}

export async function processCheckpointJob(env: Env, jobId: string): Promise<void> {
  const job = await getJob(env.DB, jobId);
  if (!job) {
    return;
  }

  if (job.sourceType !== 'checkpoint') {
    await markFailed(env.DB, job.id, 'Received checkpoint queue message for non-checkpoint job');
    return;
  }

  if (!isRunnableStatus(job.status)) {
    return;
  }

  await updateJobStatus(env.DB, job.id, 'running', {
    phase: 'building',
    started_at: job.startedAt ?? new Date().toISOString(),
  });

  try {
    await executeCheckpointBuild(env, job);
  } catch (error) {
    if (error instanceof QueueRetryError) {
      throw error;
    }

    const message = error instanceof Error ? error.message : String(error);

    try {
      await markFailed(env.DB, job.id, message);
    } catch (statusError) {
      const details = statusError instanceof Error ? statusError.message : String(statusError);
      throw new QueueRetryError(`Failed to mark checkpoint job as failed: ${details}`);
    }
  }
}

