                    assert.equal(values[values.length - 1], 'job_any');
                    return { success: true, meta: { duration: 0 } };
                  },
                };
              },
            };
          }

          return {
            bind(...values: unknown[]) {
              return {
                async first<T>() {
                  return {
                    id: values[0],
                    prompt: values[1],
                    model: 'checkpoint',
                    status: 'queued',
                    phase: 'queued',
                    created_at: '2026-03-06T10:00:00.000Z',
