                    deletedJobs += 1;
                    throw new Error('delete failed');
                  },
                };
              },
            };
          }

          if (/^UPDATE jobs SET status = \?/i.test(sql)) {
            return {
              bind(...values: unknown[]) {
                return {
                  async run() {
                    failedUpdates += 1;
                    assert.equal(values[0], 'failed');
                    assert.equal(values[values.length - 1], 'job_any');
                    return { success: true, meta: { duration: 0 } };
                  },
                };
