                    created_at: '2026-03-06T10:00:00.000Z',
                    started_at: null,
                    completed_at: null,
                    preview_url: null,
                    deployed_url: null,
                    error_message: null,
                    file_count: null,
                  } as T;
                },
              };
            },
          };
        },
      },
    } as unknown;

    const response = await handleCreateCheckpointJob(createMultipartRequest(form), env as never);
