  }

  if (job.status === 'running' && (job.phase === 'building' || job.phase === 'validating')) {
    throw new QueueRetryError(`Checkpoint job ${job.id} is currently running; retrying`);
  }

  if (job.status !== 'queued') {
    return;
  }

  const claimed = await claimQueuedCheckpointJob(env.DB, job.id);
  if (!claimed) {
    throw new QueueRetryError(`Checkpoint job ${job.id} was already claimed; retrying`);
