                };
              },
            };
          },
        };
      },
    } as unknown as D1Database;

    const events = await listJobEvents(db, 'job_abc12345', 3);
    assert.equal(events.length, 1);
    assert.equal(events[0].seq, 4);
    assert.deepEqual(events[0].payload, { x: 1 });
  }
