      phase: 'completed',
      completed_at: new Date().toISOString(),
    });

    await appendJobEvent(env.DB, {
      jobId: job.id,
      eventType: 'job_completed',
      phase: 'completed',
      payload: {
        sourceType: job.sourceType,
        commitSha: job.commitSha,
      },
    });
