                      source_bundle_key: 'jobs/job_abc12345/source/a.tar.gz',
                      source_bundle_sha256: 'f'.repeat(64),
                      source_bundle_bytes: 1234,
                    } as T;
                  },
                };
              },
            };
          }

          if (/^UPDATE jobs\s+SET status = 'running'/i.test(sql)) {
