    throw new QueueRetryError(`Failed to append job_started event: ${details}`);
  }

  try {
    await executeCheckpointBuild(env, job);
  } catch (error) {
    if (error instanceof QueueRetryError) {
      try {
        await requeueForRetry(env.DB, job.id, error.message);
